// Text Diff - Compare two texts
// Uses LCS (Longest Common Subsequence) algorithm for line-based diff

var oldText = input.get("oldText") || "";
var newText = input.get("newText") || "";
var ignoreWhitespace = input.get("ignoreWhitespace") === "true";
var contextLines = parseInt(input.get("contextLines") || "3");

try {
    // Normalize line endings
    oldText = oldText.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
    newText = newText.replace(/\r\n/g, '\n').replace(/\r/g, '\n');

    var oldLines = oldText.split('\n');
    var newLines = newText.split('\n');

    // Normalize for comparison if ignoring whitespace
    function normalize(line) {
        if (ignoreWhitespace) {
            return line.trim().replace(/\s+/g, ' ');
        }
        return line;
    }

    // Build LCS table
    var m = oldLines.length;
    var n = newLines.length;
    var dp = [];

    for (var i = 0; i <= m; i++) {
        dp[i] = [];
        for (var j = 0; j <= n; j++) {
            if (i === 0 || j === 0) {
                dp[i][j] = 0;
            } else if (normalize(oldLines[i-1]) === normalize(newLines[j-1])) {
                dp[i][j] = dp[i-1][j-1] + 1;
            } else {
                dp[i][j] = Math.max(dp[i-1][j], dp[i][j-1]);
            }
        }
    }

    // Backtrack to find diff
    var diff = [];
    var i = m;
    var j = n;

    while (i > 0 || j > 0) {
        if (i > 0 && j > 0 && normalize(oldLines[i-1]) === normalize(newLines[j-1])) {
            diff.unshift({ type: 'unchanged', oldLine: i, newLine: j, content: oldLines[i-1] });
            i--;
            j--;
        } else if (j > 0 && (i === 0 || dp[i][j-1] >= dp[i-1][j])) {
            diff.unshift({ type: 'added', oldLine: null, newLine: j, content: newLines[j-1] });
            j--;
        } else if (i > 0) {
            diff.unshift({ type: 'deleted', oldLine: i, newLine: null, content: oldLines[i-1] });
            i--;
        }
    }

    // Count statistics
    var addedCount = 0;
    var deletedCount = 0;
    var unchangedCount = 0;

    for (var d = 0; d < diff.length; d++) {
        if (diff[d].type === 'added') addedCount++;
        else if (diff[d].type === 'deleted') deletedCount++;
        else unchangedCount++;
    }

    // Generate unified diff output
    var unifiedDiff = [];
    unifiedDiff.push('--- old');
    unifiedDiff.push('+++ new');

    for (var d = 0; d < diff.length; d++) {
        var item = diff[d];
        var prefix = ' ';
        if (item.type === 'added') prefix = '+';
        else if (item.type === 'deleted') prefix = '-';
        unifiedDiff.push(prefix + item.content);
    }

    // Generate HTML diff
    var htmlDiff = [];
    htmlDiff.push('<div class="diff">');
    for (var d = 0; d < diff.length; d++) {
        var item = diff[d];
        var cls = item.type;
        var lineNum = '';
        if (item.type === 'deleted') {
            lineNum = item.oldLine + ':';
        } else if (item.type === 'added') {
            lineNum = ':' + item.newLine;
        } else {
            lineNum = item.oldLine + ':' + item.newLine;
        }
        var escapedContent = item.content
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;');
        htmlDiff.push('<div class="line ' + cls + '"><span class="line-num">' + lineNum + '</span><span class="content">' + escapedContent + '</span></div>');
    }
    htmlDiff.push('</div>');

    // Generate simple changes list
    var changes = [];
    for (var d = 0; d < diff.length; d++) {
        if (diff[d].type !== 'unchanged') {
            changes.push({
                type: diff[d].type,
                line: diff[d].type === 'added' ? diff[d].newLine : diff[d].oldLine,
                content: diff[d].content
            });
        }
    }

    var hasChanges = addedCount > 0 || deletedCount > 0;

    output.set("UnifiedDiff", unifiedDiff.join('\n'));
    output.set("HtmlDiff", htmlDiff.join('\n'));
    output.set("Changes", json.stringify(changes));
    output.set("DiffData", json.stringify(diff));
    output.set("AddedCount", addedCount);
    output.set("DeletedCount", deletedCount);
    output.set("UnchangedCount", unchangedCount);
    output.set("TotalChanges", addedCount + deletedCount);
    output.set("HasChanges", hasChanges);
    output.set("OldLineCount", oldLines.length);
    output.set("NewLineCount", newLines.length);
    output.set("HasErrors", false);
    output.set("ErrorMessage", "");

    log.info("Diff complete: +" + addedCount + " -" + deletedCount + " =" + unchangedCount);

    if (hasChanges) {
        tags.trigger("different");
    } else {
        tags.trigger("identical");
    }
    tags.trigger("success");

} catch (ex) {
    log.error("Diff failed: " + ex.message);
    output.set("HasErrors", true);
    output.set("ErrorMessage", ex.message);
    tags.trigger("error");
}
